 56	export function handleMessage(inpTextRaw: string, ctx: BookingContext): FSMResult {
 57	  const text = inpTextRaw.trim();
 58	  let c = clone(ctx);
 59	  let reply = '';
 60	
 61	  // When we need the single worker in individual mode
 62	  const soloWorker: Worker | undefined =
 63	    c.accountType === 'individual'
 64	      ? {
 65	          worker_id: c.shop_id,
 66	          name: c.config?.business?.ownerName || 'Profissional',
 67	        }
 68	      : undefined;
 69	
 70	  switch (c.step) {
 71	    case 0: // greeting already sent externally; ask for name
 72	      reply = `Olá! Sou ${c.config?.assistant?.name || 'Amanda'}, assistente virtual da ${c.config?.business?.name || 'Barbearia'}. Qual é o seu nome, por favor?`;
 73	      c.step = 1;
 74	      break;
 75	
 76	    case 1: // got the name
 77	      c.clientName = text;
 78	      c.step = 2;
 79	      reply = `Olá ${text}! Qual serviço você gostaria de agendar?`;
 80	      break;
 81	
 82	    case 2: // expect a service
 83	      c.selectedService = text;
 84	      c.step = 3;
 85	
 86	      if (c.accountType === 'individual') {
 87	        c.selectedWorker = soloWorker!;
 88	        c.step = 4;
 89	        reply = `Para qual data você gostaria de agendar seu ${text} com ${soloWorker!.name}?`;
 90	      } else {
 91	        reply = `Qual profissional você prefere para o serviço de ${text}?`;
 92	      }
 93	      break;
 94	
 95	    case 3: // enterprise only – choose worker
 96	      const candidate = c.workers.find(
 97	        (w) => w.name.toLowerCase() === text.toLowerCase() || String(w.worker_id) === text
 98	      );
 99	      if (!candidate) {
100	        reply = 'Não encontrei esse profissional. Poderia escolher um da lista disponível?';
101	        break;
102	      }
103	      c.selectedWorker = candidate;
104	      c.step = 4;
105	      reply = `Perfeito! Qual data você prefere para agendar com ${candidate.name}?`;
106	      break;
107	
108	    case 4: // date (very light validation – YYYY‑MM‑DD)
109	      if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
110	        reply = 'Formato de data inválido. Use AAAA-MM-DD, por favor.';
111	        break;
112	      }
113	      c.selectedDate = text;
114	      c.step = 5;
115	      reply = `Qual horário você prefere no dia ${text}?`;
116	      break;
117	
118	    case 5: // time HH:MM
119	      if (!/^\d{2}:\d{2}$/.test(text)) {
120	        reply = 'Formato de horário inválido. Use HH:MM, por favor.';
121	        break;
122	      }
123	      c.selectedTime = text;
124	      c.step = 6;
125	      reply = `Para confirmar: ${c.selectedService} com ${c.selectedWorker!.name} em ${c.selectedDate} às ${text}. Está correto? (Responda sim para confirmar)`;
126	      break;
127	
128	    case 6: // confirmation
129	      if (/^(sim|s)$/i.test(text)) {
130	        c.step = 0; // reset for next booking
131	        reply = '✅ Agendamento confirmado! Obrigado por escolher nossos serviços.';
132	        return {
133	          reply,
134	          context: c,
135	          appointment: {
136	            worker_id: c.selectedWorker!.worker_id,
137	            date: c.selectedDate!,
138	            start_time: c.selectedTime!,
139	            client_name: c.clientName!,
140	          },
141	        };
142	      }
143	      // if user says no → go back to service selection
144	      c.step = 2;
145	      reply = 'Tudo bem, vamos tentar novamente. Qual serviço você gostaria de agendar?';
146	      break;
147	
148	    default:
149	      reply = 'Desculpe, não entendi. Poderia repetir?';
150	  }
151	
152	  return { reply, context: c };
153	}
